function StoreChestBuy:OnItemRewardsRefresh(listView, index, row, column)
    if index < 0 then
        return nil
    end
    --printInfo(index)
    local cell = listView:NewListViewItem(CellName)
    --printInfo(index)
    --print(table.dump(StoreShared.SettingStores[StoreConstants.OpenIds.StoreItemEntry].children))
    self:RefreshRewardCell(cell.transform, self._itemData.rewards[index + 1])
    return cell
end

function StoreChestBuy:RefreshRewardCell(trans, reward)
        --local trans = self.LayoutGood:GetChild(i - 1)
        --local data = self._itemData.rewards[i]
        trans = trans:Find("GoodNode")
        local behaviour = GetLuaBehaviour(trans.gameObject, GoodNode)
        if isNull(behaviour.Env) then
            behaviour:Init()
        end
        if not isNull(behaviour.Env) then
            behaviour.Env:Reload
            (
                    { 
                        goodsId = reward.goodsId, isShowNo = true, 
                        text = "x" .. reward.num
                    }
            )
            behaviour.Env:SetClickButtonAction(function(goodsId)
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(goodsVo) then
                    GameUtils.ShowCommonTipsBoard(behaviour.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
                end
            end)
        end
end

return StoreChestBuy